-- Chef App — seven more Persian recipes from the same cookbook.
--
-- The second batch from "The Food of Life" by Najmieh Batmanglij: two kababs,
-- a khoresh and four rice dishes. All savoury, so all go under Persian. The
-- format, the citation in source_url and the skip-if-title-exists rerun guard
-- are the same as 20261030000100_persian_recipes.sql; see the notes there.
--
-- The Chelow recipe carries the book's "Rice Crust Variations" page as its
-- variation lines, because those variations are written against its steps 8
-- and 9.

do $do$
declare
  r    jsonb;
  v_id uuid;
begin
  for r in select * from jsonb_array_elements($recipes$
[
  {"title": "Mushroom Khoresh (Khoresh-e Qarch)", "cuisine": "Persian",
   "instructions": "In a Dutch oven, heat 3 tablespoons oil over medium heat and brown onions, garlic, and meat. Add salt, pepper, and turmeric, and sauté for 1 minute. Pour in water — 3 1/2 cups/840ml for meat, 2 1/2 cups/600ml for chicken. Cover and simmer over low heat for 1 1/2 hours for meat or 55 minutes for chicken, stirring occasionally.\nClean mushrooms using a damp cloth, cut off stems, and slice. Sprinkle with flour and parsley. In a wide skillet, sauté the mushrooms in 3 tablespoons oil.\nAdd mushrooms, lime juice, tomato paste, and saffron water to the meat. Cover and simmer 35 minutes over low heat.\nTaste the khoresh and adjust seasoning. Add beaten egg yolks and cumin, stirring gently. Simmer for 5 minutes over low heat.\nTransfer the khoresh to an ovenproof casserole. Cover and place in a warm oven until ready to serve. Serve hot from the same dish with chelow (saffron-steamed rice). Nush-e Jan!\nVegetarian variation: Eliminate the meat from the ingredients and from step 1, add 1 1/2 cups/360ml water, and reduce cooking time to 15 minutes. Proceed with the recipe.",
   "ingredients": [
    {"group_label": null, "name": "6 tablespoons oil, butter, or ghee", "required": true},
    {"group_label": null, "name": "2 large onions, peeled and thinly sliced", "required": true},
    {"group_label": null, "name": "2 cloves garlic, peeled and sliced", "required": true},
    {"group_label": null, "name": "1 pound (450g) stew meat (lamb, veal, or beef), or boneless, skinless chicken thighs, cut into 2-in/5cm cubes", "required": true},
    {"group_label": null, "name": "1 teaspoon sea salt", "required": true},
    {"group_label": null, "name": "1/2 teaspoon freshly ground pepper", "required": true},
    {"group_label": null, "name": "1 teaspoon turmeric", "required": true},
    {"group_label": null, "name": "1 pound (450g) fresh mushrooms", "required": true},
    {"group_label": null, "name": "1 tablespoon flour", "required": true},
    {"group_label": null, "name": "2 tablespoons chopped fresh parsley", "required": true},
    {"group_label": null, "name": "2 tablespoons fresh lime juice", "required": true},
    {"group_label": null, "name": "1 tablespoon tomato paste", "required": true},
    {"group_label": null, "name": "1/4 teaspoon ground saffron dissolved in 1 tablespoon hot water", "required": true},
    {"group_label": null, "name": "2 egg yolks, beaten", "required": true},
    {"group_label": null, "name": "1 teaspoon ground cumin", "required": true}
   ]},
  {"title": "Rice Veiled in Pastry (Polow-ye Pardehi)", "cuisine": "Persian",
   "instructions": "To make the chicken: In a sauté pan, heat the oil over medium heat. Add the chicken, onion, salt, pepper, and turmeric, and sauté for a few minutes. Add the saffron-orange blossom water, cover, and cook over low heat for 30 minutes or until the chicken is almost tender.\nTo cook the rice: In a medium saucepan, place the rice, salt, and broth, and stir gently. Bring to a boil, reduce heat to medium, cover, and cook for 15 minutes. Remove from heat and allow to cool.\nTo cook the carrots and nuts mixture: In a wide skillet, heat the oil over medium heat and sauté the onion until golden brown. Add the rest of the ingredients and sauté for 2 minutes. Add this mixture to the rice and use a fork to gently combine it thoroughly with the rice. Allow to cool.\nPreheat oven to 400°F/200°C. Oil all over a 10-in/25cm-diameter baking pan.\nLay the first sheet of filo pastry in the baking pan (allow the ends to hang well over the edges) and brush it with oil. Repeat this for 10 more sheets of filo, laying one over the other.\nPlace the rice and chicken pieces in the center of the filo on the baking pan, and form into a dome shape. Fold the filo layers across and over the top of the dome. Place a sheet of filo over the top and tuck in any overlapping edges. Use your hands to form a round, smooth filo-covered dome. Brush the top with the mixture of melted butter and oil glaze.\nBake in the center of the preheated oven for 40 minutes or until the crust is crisp and golden.\nRemove from the oven and allow to cool for 5 minutes. Unclip the side of the pan. Use an offset spatula to transfer to a round platter larger than the pastry. Cut into wedges and serve hot with a green salad. Nush-e Jan!\nVegetarian variation: Eliminate the meat from the ingredients and replace the broth with 3 cups (720ml) almond milk.\nNote: You can also use ready-made frozen puff pastry to replace the filo. Roll out 1 thawed package of puff pastry on a floured surface to 16x16 inches/40cm square. Use it in step 5 by placing it in the pan with the edges overhanging. Place the chicken and rice in the center shaping it into a dome, then bring the four corners of the pastry on top of the rice, and pinch the corners together to enclose the rice. Seal the seams and use glaze to smooth out the dome. Continue with step 7.",
   "ingredients": [
    {"group_label": "Meat", "name": "2 tablespoons oil, butter, or ghee", "required": true},
    {"group_label": "Meat", "name": "2 pounds (900g) boneless, skinless chicken thighs, cut into 3-inch/7.5cm pieces", "required": true},
