    {"group_label": "Carrots and nuts mixture", "name": "1 cup (175g) dried apricots, quartered", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "1/2 cup (80g) raw pistachio kernels", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "1/2 cup (80g) blanched almonds", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "1 1/2 cups (225g) currants", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "Zest of 1 orange", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "2 tablespoons sugar", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "1 teaspoon sea salt", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "2 teaspoons ground cardamom", "required": true},
    {"group_label": "Carrots and nuts mixture", "name": "1 teaspoon ground cinnamon", "required": true},
    {"group_label": "Pastry", "name": "10-inch/25cm spring form cake pan", "required": false},
    {"group_label": "Pastry", "name": "1 cup (240ml) oil, butter, or ghee", "required": true},
    {"group_label": "Pastry", "name": "1 package frozen filo pastry sheets (take the package out of the freezer and leave at room temperature for 2 hours; cover the filo while working to prevent it from drying)", "required": true},
