    {"group_label": "Chicken", "name": "6 Cornish hens, about 4 pounds/1.8kg, each cut into 10 pieces, or 6 pounds/2.7kg of chicken drumettes, or 4 pounds/1.8kg boneless chicken thighs cut into 2-inch/5cm pieces", "required": true},
    {"group_label": "Chicken", "name": "5 medium tomatoes, halved, or 16 cherry", "required": true},
    {"group_label": "Baste", "name": "1/2 cup (110g) butter", "required": true},
